-- ============================================================
--  KUKAT Travel Agency — Full Seed Import Script (v2)
--  Run AFTER: kukat_schema.sql + kukat_group_booking_addendum.sql
--  Insertion order respects all FK dependencies.
-- ============================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO


-- roles (5 rows)
SET IDENTITY_INSERT roles ON;
SET IDENTITY_INSERT roles OFF;

-- employees (10 rows)
SET IDENTITY_INSERT employees ON;
SET IDENTITY_INSERT employees OFF;

-- affiliations (7 rows)
SET IDENTITY_INSERT affiliations ON;
SET IDENTITY_INSERT affiliations OFF;

-- product_categories (10 rows)
SET IDENTITY_INSERT product_categories ON;
SET IDENTITY_INSERT product_categories OFF;

-- suppliers (12 rows)
SET IDENTITY_INSERT suppliers ON;
SET IDENTITY_INSERT suppliers OFF;

-- products (20 rows)
SET IDENTITY_INSERT products ON;
SET IDENTITY_INSERT products OFF;

-- destinations (12 rows)
SET IDENTITY_INSERT destinations ON;
SET IDENTITY_INSERT destinations OFF;

-- class_types (8 rows)
SET IDENTITY_INSERT class_types ON;
SET IDENTITY_INSERT class_types OFF;

-- booking_fees (6 rows)
SET IDENTITY_INSERT booking_fees ON;
SET IDENTITY_INSERT booking_fees OFF;

-- customers (100 rows)
SET IDENTITY_INSERT customers ON;
SET IDENTITY_INSERT customers OFF;

-- credit_cards (80 rows)
SET IDENTITY_INSERT credit_cards ON;
SET IDENTITY_INSERT credit_cards OFF;

