-- ============================================================
--  VERIFY — run after import to confirm row counts
-- ============================================================
SELECT 'roles'               AS [table], COUNT(*) AS [rows] FROM roles
UNION ALL SELECT 'employees',              COUNT(*) FROM employees
UNION ALL SELECT 'affiliations',           COUNT(*) FROM affiliations
UNION ALL SELECT 'product_categories',     COUNT(*) FROM product_categories
UNION ALL SELECT 'suppliers',              COUNT(*) FROM suppliers
UNION ALL SELECT 'products',               COUNT(*) FROM products
UNION ALL SELECT 'destinations',           COUNT(*) FROM destinations
UNION ALL SELECT 'class_types',            COUNT(*) FROM class_types
UNION ALL SELECT 'booking_fees',           COUNT(*) FROM booking_fees
UNION ALL SELECT 'customers',              COUNT(*) FROM customers
UNION ALL SELECT 'credit_cards',           COUNT(*) FROM credit_cards
UNION ALL SELECT 'reward_programs',        COUNT(*) FROM reward_programs
UNION ALL SELECT 'bookings',               COUNT(*) FROM bookings
UNION ALL SELECT 'booking_customers',      COUNT(*) FROM booking_customers
UNION ALL SELECT 'invoices',               COUNT(*) FROM invoices
UNION ALL SELECT 'payments',               COUNT(*) FROM payments
UNION ALL SELECT 'commissions',            COUNT(*) FROM commissions
UNION ALL SELECT 'commission_payments',    COUNT(*) FROM commission_payments
ORDER BY [table];
